mapper.select:
SELECT i.*,
b.user_name as nickName
FROM invoice i,
tb_user b
WHERE i.user_id = b.user_id

    and i.indent_number like concat("%",#{indentNumber},"%")


    and i.status = #{status}


    and i.user_id = #{userId}


    and i.user_phone like concat("%",#{phone},"%")


    and date_format(i.create_time,'%Y-%m-%d') >= #{startTime}


    and date_format(i.create_time,'%Y-%m-%d') <= #{endTime}

order by i.create_time desc

select * from invoice
where 1=1

    and user_type = #{userType}


    and invoiceTitle concat("%",#{invoiceTitle},"%")


    and taxpayer_number concat("%",#{taxpayerNumber},"%")


    and invoice_type = #{invoiceType}


    and invoice_type concat("%",#{bankDeposit},"%")


    and user_phone concat("%",#{userPhone},"%")


    and invoice_id = #{indentId}


    and status = #{status}


    and date_format(i.create_time,'%Y-%m-%d') BETWEEN #{startTime} and #{endTime}


    and date_format(i.create_time,'%Y-%m-%d') >= #{startTime}


    and date_format(i.create_time,'%Y-%m-%d') <= #{endTime}

order by create_time desc
